const ESPEC={INST:'Instrumentista',REFR:'Refratarista',ISOL:'Isolador',PINT:'Pintor industrial',ACESSO:'Montador de andaime',LIMP:'Montador de andaime',END:'Inspetor de END nível 2',MED:'Inspetor de END nível 2',SUBST:'Inspetora de soldagem'};
function pessoaPara(grupo,r,tipo){const l=EFETIVO.filter(e=>e.grupo===grupo);if(!l.length)return EFETIVO[0];
  const esp=ESPEC[tipo]&&l.find(e=>e.funcao.startsWith(ESPEC[tipo]));if(esp)return esp;
  if(grupo==='Complementar / Produção')return l.find(e=>e.funcao==='Montador de andaime');
  if(grupo==='Inspeção')return l.find(e=>e.funcao.startsWith('Inspetora de equipamentos'));
  return l[Math.floor(r*l.length)%l.length]}
/* ================= estado de exemplo das plaquetas, coerente com o painel de zonas ================= */
function hash(s){let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return(h>>>0)/4294967296}
const ZN=(fo,cod)=>(FORNOS[fo].zonas||[]).find(z=>z.cod===cod);
const pendUsada={};
ITENS.forEach(p=>{const n=TIPOS[p.tipo].e.length,z=ZN(p.forno,p.zonas[0]),est=z?z.estado:'nao',r=hash(p.id);p.reg=[];p.estado='nao';p.feitas=0;
  if(p.canc){p.estado='canc';return}
  if(est==='lib'){p.feitas=n}
  else if(est==='nao'){p.feitas=0}
  else if(est==='esp'){p.feitas=Math.max(1,n-1-(r<.5?1:0))}
  else if(est==='pen'){p.feitas=Math.max(1,Math.floor(n*.5));if(!pendUsada[p.forno+p.zonas[0]]&&['END','MED','QUEI'].includes(p.tipo)){pendUsada[p.forno+p.zonas[0]]=1;p.pend=z.rec||'Resultado fora do critério. Aguarda avaliação da engenharia.'}}
  else{p.feitas=Math.min(n-1,Math.floor(n*(.25+r*.5)))}
  for(let i=0;i<p.feitas;i++){const et=TIPOS[p.tipo].e[i];{const pe=pessoaPara(et[1],hash(p.id+i),p.tipo);p.reg.push({et:i,quando:dataRec(p.feitas-1-i,hash(p.id+'d'+i)),quem:pe.nome,fn:pe.funcao,res:'Sim',fotos:et[1]==='Inspeção'?2:1})}}
  p.estado=p.pend?'pen':p.feitas>=n?'lib':p.feitas===0?'nao':(TIPOS[p.tipo].e[p.feitas][1]==='Inspeção'?'esp':'and')});
