const escopo=Object.entries(TIPOS).map(([k,t])=>{const l=ATV.filter(p=>p.tipo===k);if(!l.length)return null;
  const et=l.reduce((a,p)=>a+nEt(p),0),fe=l.reduce((a,p)=>a+p.feitas,0);
  return [t.n.toUpperCase(),l.length,l.filter(p=>p.feitas>0).length,l.filter(p=>p.feitas>0&&st(p)!=='lib').length,l.filter(p=>st(p)==='pen').length,et?fe*100/et:0,l.filter(p=>st(p)==='lib').length]}).filter(Boolean).sort((a,b)=>b[1]-a[1]);
